properties.query:
let exploit_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("mshta.exe", "certutil.exe", "bitsadmin.exe") and ParentProcessName !has_any ("explorer.exe", "task scheduler") | summarize exploit_time=min(TimeGenerated) by Computer;
let enum_events = SecurityEvent | where EventID in (4662, 5136) and Properties has_any ("Domain Admins", "Enterprise Admins", "DNS") | summarize enum_time=min(TimeGenerated) by SubjectUserName;
exploit_events | join kind=inner enum_events on $left.Computer == $right.Computer | where enum_time - exploit_time between (0min .. 60min)
